= SlateportCity_PokemonFanClub_EventScript_SwaggerTutor
lock
faceplayer
goto_if_set FLAG_MOVE_TUTOR_TAUGHT_SWAGGER MoveTutor_EventScript_SwaggerTaught
msgboxyesno	Heh! My POKéMON totally rules! It's cooler than any POKéMON!I was lipping off with a swagger in my step like that when the CHAIRMAN chewed me out.That took the swagger out of my step.If you'd like, I'll teach the move SWAGGER to a POKéMON of yours.
goto_if_eq VAR_RESULT NO MoveTutor_EventScript_SwaggerDeclined
call MoveTutor_EventScript_CanOnlyBeLearnedOnce
goto_if_eq VAR_RESULT NO MoveTutor_EventScript_SwaggerDeclined
msgbox	Gut, welches POKéMON soll ANGEBEN erlernen?
setvar VAR_0x8005 TUTOR_MOVE_SWAGGER
call MoveTutor_EventScript_OpenPartyMenu
goto_if_eq VAR_RESULT 0 MoveTutor_EventScript_SwaggerDeclined
setflag FLAG_MOVE_TUTOR_TAUGHT_SWAGGER
goto MoveTutor_EventScript_SwaggerTaught
end
= MoveTutor_EventScript_SwaggerTaught
msgbox	Ich werde mein POKéMON von nun an einfach ohne ANGEBEN loben.
release
end
= MoveTutor_EventScript_SwaggerDeclined
msgbox	Was, nein? Kannst du dich nicht auf die Sache einlassen?
release
end
= MoveTutor_EventScript_OpenPartyMenu
special ChooseMonForMoveTutor
lock
faceplayer
return
= MoveTutor_EventScript_CanOnlyBeLearnedOnce
msgboxyesno	This move can be learned only once. Is that okay?
return
= SlateportCity_PokemonFanClub_EventScript_Azumarill
lock
faceplayer
waitse
playmoncry SPECIES_AZUMARILL CRY_MODE_NORMAL
msgbox	AZUMARILL: Marimari?
waitmoncry
release
end
= SlateportCity_PokemonFanClub_EventScript_Skitty
lock
faceplayer
waitse
playmoncry SPECIES_SKITTY CRY_MODE_NORMAL
msgbox	SKITTY: Fffnyaaaah…
waitmoncry
release
end
= SlateportCity_PokemonFanClub_EventScript_Zigzagoon
lock
faceplayer
waitse
playmoncry SPECIES_ZIGZAGOON CRY_MODE_NORMAL
msgbox	ZIGZAGOON: Kyuuu…
waitmoncry
release
end
= SlateportCity_PokemonFanClub_EventScript_Chairman
lock
faceplayer
goto_if_unset FLAG_ENTERED_CONTEST SlateportCity_PokemonFanClub_EventScript_ChairmanNotEnteredContest
call_if_unset FLAG_MET_SLATEPORT_FANCLUB_CHAIRMAN SlateportCity_PokemonFanClub_EventScript_MeetChairman
switch VAR_SLATEPORT_FAN_CLUB_STATE
case 0 SlateportCity_PokemonFanClub_EventScript_ChairmanFirstAssessment
case 1 SlateportCity_PokemonFanClub_EventScript_ChairmanTryAssessPokemon
case 2 SlateportCity_PokemonFanClub_EventScript_NoMoreScarves
release
end
= SlateportCity_PokemonFanClub_EventScript_NoMoreScarves
msgbox	Es tut mir leid, aber ich habe nichts mehr für dich! Gar nichts!Schließlich hast du das Talent, POKéMON auch ganz ohne Items großzuziehen!
release
end
= SlateportCity_PokemonFanClub_EventScript_ChairmanTryAssessPokemon
setvar VAR_TEMP_2 0
call_if_set FLAG_RECEIVED_YELLOW_SCARF SlateportCity_PokemonFanClub_EventScript_CountReceivedScarf
call_if_set FLAG_RECEIVED_GREEN_SCARF SlateportCity_PokemonFanClub_EventScript_CountReceivedScarf
call_if_set FLAG_RECEIVED_PINK_SCARF SlateportCity_PokemonFanClub_EventScript_CountReceivedScarf
call_if_set FLAG_RECEIVED_BLUE_SCARF SlateportCity_PokemonFanClub_EventScript_CountReceivedScarf
call_if_set FLAG_RECEIVED_RED_SCARF SlateportCity_PokemonFanClub_EventScript_CountReceivedScarf
call_if_eq VAR_TEMP_2 CONTEST_CATEGORIES_COUNT SlateportCity_PokemonFanClub_EventScript_ReceivedAllScarves
goto_if_eq VAR_SLATEPORT_FAN_CLUB_STATE 2 SlateportCity_PokemonFanClub_EventScript_NoMoreScarves
msgbox	Wie wächst dein POKéMON heran? Lass es mich mal untersuchen.
goto SlateportCity_PokemonFanClub_EventScript_ChairmanAssessLeadMon
end
= SlateportCity_PokemonFanClub_EventScript_ChairmanAssessLeadMon
msgbox	Hm, hm… Ich verstehe…
setvar VAR_TEMP_1 0
call_if_unset FLAG_RECEIVED_YELLOW_SCARF SlateportCity_PokemonFanClub_EventScript_CheckMonTough
call_if_unset FLAG_RECEIVED_GREEN_SCARF SlateportCity_PokemonFanClub_EventScript_CheckMonSmart
call_if_unset FLAG_RECEIVED_PINK_SCARF SlateportCity_PokemonFanClub_EventScript_CheckMonCute
call_if_unset FLAG_RECEIVED_BLUE_SCARF SlateportCity_PokemonFanClub_EventScript_CheckMonBeauty
call_if_unset FLAG_RECEIVED_RED_SCARF SlateportCity_PokemonFanClub_EventScript_CheckMonCool
bufferleadmonspeciesname STR_VAR_1
switch VAR_TEMP_1
case 0 SlateportCity_PokemonFanClub_EventScript_NoHighConditions
case 1 SlateportCity_PokemonFanClub_EventScript_GiveRedScarf
case 2 SlateportCity_PokemonFanClub_EventScript_GiveBlueScarf
case 3 SlateportCity_PokemonFanClub_EventScript_GivePinkScarf
case 4 SlateportCity_PokemonFanClub_EventScript_GiveGreenScarf
case 5 SlateportCity_PokemonFanClub_EventScript_GiveYellowScarf
release
end
= SlateportCity_PokemonFanClub_EventScript_GiveYellowScarf
checkitemspace ITEM_YELLOW_SCARF
goto_if_eq VAR_RESULT FALSE SlateportCity_PokemonFanClub_EventScript_NoRoomForScarf
msgbox	Dein STR_VAR_1 wächst wirklich beeindruckend heran! Es ist ein wahres Prachtexemplar!Aber! Wenn du ihm das hier gibst, würde es noch besser gedeihen! Wirklich wahr!
setflag FLAG_RECEIVED_YELLOW_SCARF
giveitem ITEM_YELLOW_SCARF
msgbox	Lass ein POKéMON dieses GELBE TUCH tragen.Es wird die Zähigkeit deines POKéMON noch viel mehr steigern!
release
end
= SlateportCity_PokemonFanClub_EventScript_NoRoomForScarf
msgbox	Oh, du meine Güte…Dein POKéMON wächst sehr gut heran, also hast du dir eine Belohnung verdient.Leider hast du keinen Platz mehr dafür in deiner TASCHE.
release
end
= SlateportCity_PokemonFanClub_EventScript_GiveGreenScarf
checkitemspace ITEM_GREEN_SCARF
goto_if_eq VAR_RESULT FALSE SlateportCity_PokemonFanClub_EventScript_NoRoomForScarf
msgbox	Dein STR_VAR_1 wächst wirklich beeindruckend heran! Es ist ein wahres Prachtexemplar!Aber! Wenn du ihm das hier gibst, würde es noch besser gedeihen! Wirklich wahr!
setflag FLAG_RECEIVED_GREEN_SCARF
giveitem ITEM_GREEN_SCARF
msgbox	Lass ein POKéMON dieses GRÜNE TUCH tragen.Das steigert die Klugheit von POKéMON!
release
end
= SlateportCity_PokemonFanClub_EventScript_GivePinkScarf
checkitemspace ITEM_PINK_SCARF
goto_if_eq VAR_RESULT FALSE SlateportCity_PokemonFanClub_EventScript_NoRoomForScarf
msgbox	Dein STR_VAR_1 wächst wirklich beeindruckend heran! Es ist ein wahres Prachtexemplar!Aber! Wenn du ihm das hier gibst, würde es noch besser gedeihen! Wirklich wahr!
setflag FLAG_RECEIVED_PINK_SCARF
giveitem ITEM_PINK_SCARF
msgbox	Lass ein POKéMON dieses PINKE TUCH tragen.Es bringt die Niedlichkeit des POKéMON noch mehr zur Geltung!
release
end
= SlateportCity_PokemonFanClub_EventScript_GiveBlueScarf
checkitemspace ITEM_BLUE_SCARF
goto_if_eq VAR_RESULT FALSE SlateportCity_PokemonFanClub_EventScript_NoRoomForScarf
msgbox	Dein STR_VAR_1 wächst wirklich beeindruckend heran! Es ist ein wahres Prachtexemplar!Aber! Wenn du ihm das hier gibst, würde es noch besser gedeihen! Wirklich wahr!
setflag FLAG_RECEIVED_BLUE_SCARF
giveitem ITEM_BLUE_SCARF
msgbox	Lass ein POKéMON dieses BLAUE TUCH tragen.Seine Schönheit wird dadurch noch viel mehr betont!
release
end
= SlateportCity_PokemonFanClub_EventScript_GiveRedScarf
checkitemspace ITEM_RED_SCARF
goto_if_eq VAR_RESULT FALSE SlateportCity_PokemonFanClub_EventScript_NoRoomForScarf
msgbox	Dein STR_VAR_1 wächst wirklich beeindruckend heran! Es ist ein wahres Prachtexemplar!Aber! Wenn du ihm das hier gibst, würde es noch besser gedeihen! Wirklich wahr!
setflag FLAG_RECEIVED_RED_SCARF
giveitem ITEM_RED_SCARF
msgbox	Lass ein POKéMON dieses ROTE TUCH tragen.Jeder wird die Coolness dieses POKéMON erkennen!
release
end
= SlateportCity_PokemonFanClub_EventScript_NoHighConditions
msgbox	Hmmm… Es ist nicht schlecht, aber auch nicht gut…Du, der TRAINER, musst dir mehr Mühe geben, dieses POKéMON großzuziehen!Darf ich zum Beispiel vorschlagen, ihm mehr S zu geben?
release
end
= SlateportCity_PokemonFanClub_EventScript_CheckMonCool
specialvar VAR_RESULT CheckLeadMonCool
call_if_eq VAR_RESULT TRUE SlateportCity_PokemonFanClub_EventScript_SetMonCool
return
= SlateportCity_PokemonFanClub_EventScript_SetMonCool
setvar VAR_TEMP_1 1
return
= SlateportCity_PokemonFanClub_EventScript_CheckMonBeauty
specialvar VAR_RESULT CheckLeadMonBeauty
call_if_eq VAR_RESULT TRUE SlateportCity_PokemonFanClub_EventScript_SetMonBeauty
return
= SlateportCity_PokemonFanClub_EventScript_SetMonBeauty
setvar VAR_TEMP_1 2
return
= SlateportCity_PokemonFanClub_EventScript_CheckMonCute
specialvar VAR_RESULT CheckLeadMonCute
call_if_eq VAR_RESULT TRUE SlateportCity_PokemonFanClub_EventScript_SetMonCute
return
= SlateportCity_PokemonFanClub_EventScript_SetMonCute
setvar VAR_TEMP_1 3
return
= SlateportCity_PokemonFanClub_EventScript_CheckMonSmart
specialvar VAR_RESULT CheckLeadMonSmart
call_if_eq VAR_RESULT TRUE SlateportCity_PokemonFanClub_EventScript_SetMonSmart
return
= SlateportCity_PokemonFanClub_EventScript_SetMonSmart
setvar VAR_TEMP_1 4
return
= SlateportCity_PokemonFanClub_EventScript_CheckMonTough
specialvar VAR_RESULT CheckLeadMonTough
call_if_eq VAR_RESULT TRUE SlateportCity_PokemonFanClub_EventScript_SetMonTough
return
= SlateportCity_PokemonFanClub_EventScript_SetMonTough
setvar VAR_TEMP_1 5
return
= SlateportCity_PokemonFanClub_EventScript_ReceivedAllScarves
setvar VAR_SLATEPORT_FAN_CLUB_STATE 2
return
= SlateportCity_PokemonFanClub_EventScript_CountReceivedScarf
addvar VAR_TEMP_2 1
return
= SlateportCity_PokemonFanClub_EventScript_ChairmanFirstAssessment
setvar VAR_SLATEPORT_FAN_CLUB_STATE 1
msgbox	Ähem! Ich sehe, du hast an einem POKéMON-CONTEST teilgenommen!Bitte! Lass mich untersuchen, wie du dein POKéMON großgezogen hast.Es erfreut mich ungemein, POKéMON zu sehen, die von anderen TRAINERN aufgezogen wurden.Der glückliche Ausdruck von POKéMON, die mit rechter Sorgfalt aufgezogen wurden…Der gütige Blick des TRAINERS, der das POKéMON gehegt und gepflegt hat…Schon der Gedanke daran erfüllt mein Herz mit überwältigender Freude.Oh! Ich bitte um Verzeihung! Vergib mir mein Geschwätz!Bitte! Lass mich untersuchen, wie sehr dein POKéMON gewachsen ist!
goto SlateportCity_PokemonFanClub_EventScript_ChairmanAssessLeadMon
end
= SlateportCity_PokemonFanClub_EventScript_MeetChairman
msgbox	Ähem! Ich bin der VORSITZENDE des POKéMON-FANCLUBS!Als VORSITZENDER bin ich natürlich der Wichtigste!Niemand übertrifft mich im Großziehen von POKéMON. Niemand!Nun, lass mich dir von POKéMON-CONTESTS erzählen.Das sind Veranstaltungen, bei denen man seine POKéMON der ganzen Welt zeigen kann!Sie finden allerdings in fernen Städten statt, also kann ich nicht oft genug teilnehmen.Deshalb versammeln wir uns hier, um unsere POKéMON zu zeigen und die der anderen zu bewundern.
setflag FLAG_MET_SLATEPORT_FANCLUB_CHAIRMAN
return
= SlateportCity_PokemonFanClub_EventScript_ChairmanNotEnteredContest
goto_if_set FLAG_MET_SLATEPORT_FANCLUB_CHAIRMAN SlateportCity_PokemonFanClub_EventScript_ChairmanEnterContest
msgbox	Ähem! Ich bin der VORSITZENDE des POKéMON-FANCLUBS!Als VORSITZENDER bin ich natürlich der Wichtigste!Niemand übertrifft mich im Großziehen von POKéMON. Niemand!Nun, lass mich dir von POKéMON-CONTESTS erzählen.Das sind Veranstaltungen, bei denen man seine POKéMON der ganzen Welt zeigen kann!Sie finden allerdings in fernen Städten statt, also kann ich nicht oft genug teilnehmen.Deshalb versammeln wir uns hier, um unsere POKéMON zu zeigen und die der anderen zu bewundern.
setflag FLAG_MET_SLATEPORT_FANCLUB_CHAIRMAN
release
end
= SlateportCity_PokemonFanClub_EventScript_ChairmanEnterContest
msgbox	Das POKéMON eines TRAINERS, der an einem POKéMON-CONTEST teilgenommen hat… Das würde ich gerne sehen.
release
end
= SlateportCity_PokemonFanClub_EventScript_SootheBellWoman
lock
faceplayer
goto_if_set FLAG_RECEIVED_SOOTHE_BELL SlateportCity_PokemonFanClub_EventScript_ReceivedSootheBell
msgbox	Ich liebe es, POKéMON zu sehen, die ihre TRAINER lieben.POKéMON spüren die Gefühle ihrer TRAINER ganz genau.Wenn du dein POKéMON mit Liebe und Fürsorge behandelst, wird es dich auch lieben.Wenn dein POKéMON dich lieb gewonnen hat, zeig es mir bitte!
specialvar VAR_RESULT GetLeadMonFriendshipScore
goto_if_ge VAR_RESULT FRIENDSHIP_150_TO_199 SlateportCity_PokemonFanClub_EventScript_GiveSootheBell
release
end
= SlateportCity_PokemonFanClub_EventScript_GiveSootheBell
playse SE_PIN
applymovement VAR_LAST_TALKED Common_Movement_ExclamationMark
waitmovement 0
applymovement VAR_LAST_TALKED Common_Movement_Delay48
waitmovement 0
msgbox	Dein POKéMON vergöttert dich wirklich.Für dich, einen so mitfühlenden TRAINER, ein Geschenk vom FANCLUB!
giveitem ITEM_SOOTHE_BELL
goto_if_eq VAR_RESULT FALSE Common_EventScript_ShowBagIsFull
setflag FLAG_RECEIVED_SOOTHE_BELL
release
end
= SlateportCity_PokemonFanClub_EventScript_ReceivedSootheBell
msgbox	POKéMON spüren die Gefühle ihrer TRAINER ganz genau.Wenn du dein POKéMON mit Liebe und Fürsorge behandelst, wird es dich auch lieben.
release
end
= SlateportCity_PokemonFanClub_EventScript_Reporter
lock
faceplayer
specialvar VAR_RESULT IsLeadMonNicknamedOrNotEnglish
goto_if_eq VAR_RESULT FALSE SlateportCity_PokemonFanClub_EventScript_ReporterNoNickname
setvar VAR_0x8005 TVSHOW_PKMN_FAN_CLUB_OPINIONS
special InterviewBefore
goto_if_eq VAR_RESULT TRUE SlateportCity_PokemonFanClub_EventScript_AlreadyInterviewed
copyvar VAR_0x8009 VAR_0x8006
msgboxyesno	Wow!It's plain to see that you lavish your love on your STR_VAR_1.Okay, it's named STR_VAR_2.Can I ask you a favor?I'm a TV reporter, and I'm running a survey on POKéMON.Would you be willing to answer a few simple questions for me?
goto_if_eq VAR_RESULT YES SlateportCity_PokemonFanClub_EventScript_AcceptInterview
goto_if_eq VAR_RESULT NO SlateportCity_PokemonFanClub_EventScript_DeclineInterview
end
= SlateportCity_PokemonFanClub_EventScript_DeclineInterview
msgbox	Oh, na gut…Nun, wenn du mir mal von POKéMON erzählen möchtest, bin ich hier!
release
end
= SlateportCity_PokemonFanClub_EventScript_AcceptInterview
msgbox	Super! Danke!Okay, los geht's. Ich brauche nur schnelle Antworten, okay?
random 3
copyvar VAR_0x800A VAR_RESULT
switch VAR_RESULT
case 0 SlateportCity_PokemonFanClub_EventScript_RandomQuestion1
case 1 SlateportCity_PokemonFanClub_EventScript_RandomQuestion2
case 2 SlateportCity_PokemonFanClub_EventScript_RandomQuestion3
end
= SlateportCity_PokemonFanClub_EventScript_RandomQuestion3
msgbox	Diese Frage betrifft auch dein geliebtes STR_VAR_1.Was hat dich an STR_VAR_1 so angezogen?
goto SlateportCity_PokemonFanClub_EventScript_ContinueInterview
end
= SlateportCity_PokemonFanClub_EventScript_ContinueInterview
setvar VAR_0x8004 EASY_CHAT_TYPE_FAN_CLUB
copyvar VAR_0x8005 VAR_0x8009
setvar VAR_0x8006 0
call Common_ShowEasyChatScreen
lock
faceplayer
goto_if_eq VAR_RESULT 0 SlateportCity_PokemonFanClub_EventScript_DeclineInterview
msgbox	Okay, das ergibt Sinn.Die nächste Frage ist vielleicht etwas kniffliger.Los geht's…Was bedeuten POKéMON für dich?
setvar VAR_0x8006 1
call Common_ShowEasyChatScreen
lock
faceplayer
goto_if_eq VAR_RESULT 0 SlateportCity_PokemonFanClub_EventScript_DeclineInterview
msgbox	Aha!Hmhm…Okay! Danke für deine Hilfe.Es war lustig und aufschlussreich, mit dir zu plaudern.Es kann sein, dass unser Interview im Fernsehen landet. Schau doch mal rein!Okay, das war's. Tschüssikowski!
copyvar VAR_0x8007 VAR_0x800A
setvar VAR_0x8005 TVSHOW_PKMN_FAN_CLUB_OPINIONS
goto Interview_EventScript_EndInterview
end
= Interview_EventScript_EndInterview
special InterviewAfter
incrementgamestat GAME_STAT_GOT_INTERVIEWED
release
end
@ Shares reporter object with TVSHOW_PKMN_FAN_CLUB_OPINIONS
goto SlateportCity_PokemonFanClub_EventScript_ReporterNoNickname
= SlateportCity_PokemonFanClub_EventScript_ReporterNoNickname
setvar VAR_0x8005 TVSHOW_FAN_CLUB_LETTER
special InterviewBefore
goto_if_eq VAR_RESULT TRUE SlateportCity_PokemonFanClub_EventScript_AlreadyInterviewed2
copyvar VAR_0x8009 VAR_0x8006
msgboxyesno	Hi, you seem to be very close to your STR_VAR_1.Do you know what? I'm a TV reporter.I travel around interviewing people about POKéMON.I'm wondering if you'd be willing to tell me a little about your STR_VAR_1?
goto_if_eq VAR_RESULT YES SlateportCity_PokemonFanClub_EventScript_AcceptInterview2
goto_if_eq VAR_RESULT NO SlateportCity_PokemonFanClub_EventScript_DeclineInterview2
end
= SlateportCity_PokemonFanClub_EventScript_DeclineInterview2
msgbox	Oh, na gut…Nun, wenn du mir mal von POKéMON erzählen möchtest, bin ich hier!
release
end
= SlateportCity_PokemonFanClub_EventScript_AcceptInterview2
msgbox	Wow, danke!Okay, dann erzähl mir doch, was du möchtest, über dein STR_VAR_1.
setvar VAR_0x8004 EASY_CHAT_TYPE_INTERVIEW
copyvar VAR_0x8005 VAR_0x8009
setvar VAR_0x8006 EASY_CHAT_PERSON_REPORTER_FEMALE
call Common_ShowEasyChatScreen
lock
faceplayer
goto_if_eq VAR_RESULT 1 SlateportCity_PokemonFanClub_EventScript_SubmitResponse2
goto_if_eq VAR_RESULT 0 SlateportCity_PokemonFanClub_EventScript_DeclineInterview2
end
= SlateportCity_PokemonFanClub_EventScript_SubmitResponse2
msgbox	Wow… Das ist eine interessante Geschichte.Du bist wirklich eng verbunden mit STR_VAR_1, nicht wahr?Ich habe das Gefühl, dass deine Geschichte eine tolle TV-Story abgeben würde.Ich verspreche, ich mache daraus eine unterhaltsame Sendung. Halt die Augen offen!Okay, das war's. Tschüssikowski!
setvar VAR_0x8005 TVSHOW_FAN_CLUB_LETTER
goto Interview_EventScript_EndInterview
end
= SlateportCity_PokemonFanClub_EventScript_AlreadyInterviewed2
msgbox	Ich liebe diesen Job--man erfährt bei Interviews so viel über POKéMON.
release
end
= SlateportCity_PokemonFanClub_EventScript_RandomQuestion2
msgbox	Dein STR_VAR_1 wird liebevoll umsorgt.Wenn du es mit etwas vergleichen würdest, das du magst, was wäre das?
goto SlateportCity_PokemonFanClub_EventScript_ContinueInterview
end
= SlateportCity_PokemonFanClub_EventScript_RandomQuestion1
msgbox	Was hast du gefühlt, als du STR_VAR_1 zum ersten Mal getroffen hast?Wie würdest du deine Gefühle von damals beschreiben?
goto SlateportCity_PokemonFanClub_EventScript_ContinueInterview
